from AutoCorrelation import AutoCorrelationSingleVariable
from JacknifePrograms import *
import matplotlib.pyplot as plt

from MesonMassEM.Mass.CorrelatedFitGPT import ChiralFit_U, ChiralFit_D

hd = "580"
folderHeads = f"H:\\MesonMassElectric\\{hd}01\\Chiral\\"
# folderHeads = "H:\\BS01Polyakov\\"

chiral580light = [2.314405661598166, 4.026407228363287, 2.4878096122236317, 2.718666556894974, 2.3555386766172144, 2.24332116899659, 3.612663793127009, 2.6971839796743]
chiral580heavy = [2.3286543520424288, 4.557582921106412, 2.88067129829685, 2.6821055494011548, 3.0617263269463995, 2.8908861894244615, 4.175201818770819, 2.9720750795588575]

sliceCount = 24

# ud-ele
frA = np.zeros((2, 8))
frAe = np.zeros((2, 8))
frB = np.zeros((2, 8))
frBe = np.zeros((2, 8))
frchi = np.zeros((2, 8))

for lhidx in range(0, 2):
    lh = (0 == lhidx)
    cv = []
    sv = []
    for i in range(0, 8):
        print(f"lh={lhidx}, e={i}")
        if lh:
            fileNames = folderHeads + f"EC{hd}_01_M0__{i}_condensateXSlicepCCLightChiralKS.csv"
        else:
            fileNames = folderHeads + f"EC{hd}_01_M0__{i}_condensateXSlicepCCHeavyChiralKS.csv"
        testarray = LoadMathematicaCSV(fileNames)
        testarrayre = -np.real(testarray) / 2
        testarrayre = testarrayre[100:,:]
        resre = []
        resree = []
        for j in range(sliceCount):
            v, s = JacknifeMean(testarrayre[:,j])
            resre.append(v)
            if lh:
                resree.append(s * np.sqrt(2 * chiral580light[i]))
            else:
                resree.append(s * np.sqrt(2 * chiral580heavy[i]))
        if lh:
            if 100 != i:
                a, ae, b, be, chi2 = ChiralFit_U(testarrayre, i)
                frA[lhidx, i] = a
                frAe[lhidx, i] = ae * np.sqrt(2 * chiral580light[i])
                frB[lhidx, i] = b
                frBe[lhidx, i] = be * np.sqrt(2 * chiral580light[i])
                frchi[lhidx, i] = chi2 / (2 * chiral580light[i])
            else:
                a, ae, b, be, chi2 = ChiralFit_U(testarrayre, i, svd_cut=1.0e-10)
                frA[lhidx, i] = a
                frAe[lhidx, i] = ae * np.sqrt(2 * chiral580light[i])
                frB[lhidx, i] = b
                frBe[lhidx, i] = be * np.sqrt(2 * chiral580light[i])
                frchi[lhidx, i] = chi2 / (2 * chiral580light[i])
        else:
            if 5 == i:
                a, ae, b, be, chi2 = ChiralFit_D(testarrayre, i, svd_cut=1.0e-13)
                frA[lhidx, i] = a
                frAe[lhidx, i] = ae * np.sqrt(2 * chiral580heavy[i])
                frB[lhidx, i] = b
                frBe[lhidx, i] = be * np.sqrt(2 * chiral580heavy[i])
                frchi[lhidx, i] = chi2 / (2 * chiral580heavy[i])
            elif 6 == i:
                a, ae, b, be, chi2 = ChiralFit_D(testarrayre, i, svd_cut=2.5e-9)
                frA[lhidx, i] = a
                frAe[lhidx, i] = ae * np.sqrt(2 * chiral580heavy[i])
                frB[lhidx, i] = b
                frBe[lhidx, i] = be * np.sqrt(2 * chiral580heavy[i])
                frchi[lhidx, i] = chi2 / (2 * chiral580heavy[i])
            else:
                a, ae, b, be, chi2 = ChiralFit_D(testarrayre, i)
                frA[lhidx, i] = a
                frAe[lhidx, i] = ae * np.sqrt(2 * chiral580heavy[i])
                frB[lhidx, i] = b
                frBe[lhidx, i] = be * np.sqrt(2 * chiral580heavy[i])
                frchi[lhidx, i] = chi2 / (2 * chiral580heavy[i])
        plt.plot([n for n in range(sliceCount)], resre)
        plt.show()
        resre = np.array(resre)
        resree = np.array(resree)
        cv.append(resre)
        sv.append(resree)

    print(PrintAsMatlabArray(cv, "vu" if lh else "vd"))
    print(PrintAsMatlabArray(sv, "su" if lh else "sd"))




